<script>import {formatValue,formatTime} from '$lib/energy';import Icon from './Icon.svelte';let {data,preview=false}=$props();let metrics=$derived(data.snapshot?.metrics || {});const readings=[['batteryVoltage','Battery voltage','V'],['batteryCurrent','Battery current','A'],['batteryPower','Battery power','W'],['batterySoc','Battery state of charge','%'],['grid','Grid power','W'],['generator','Generator power','W']];</script>
<div class="page-heading"><div><div class="breadcrumb">MY RESIDENCE <span>/</span> SYSTEM DETAILS</div><h1>Know your system.</h1><p>{data.node?.display_name || 'Residence assignment pending'} <span>·</span> {data.node?.reference || 'Node pending'}</p></div><span class="panel-tag">Read-only monitoring</span></div>
{#if data.status==='awaiting_installation'}<div class="notice neutral"><Icon name="info"/><div><strong>Your system is being linked.</strong><p>GridUbuntu is confirming the solar installation assigned to this residence. Your account name can differ from the equipment provider's site name.</p></div></div>{/if}
<div class="system-grid"><section class="panel"><div class="panel-heading"><div><span class="overline">CONNECTION</span><h2>Installation overview</h2></div><Icon name="system"/></div><div class="health-row"><span>Node reference</span><strong>{data.node?.reference || 'Not assigned'}</strong></div><div class="health-row"><span>Equipment provider</span><strong>Victron</strong></div><div class="health-row"><span>Location</span><strong>{data.node?.location_label || 'Not configured'}</strong></div><div class="health-row"><span>Last reported reading</span><strong>{formatTime(data.snapshot?.reportedAt)}</strong></div><div class="health-row"><span>Measurement verification</span><strong>{preview?'Illustrative only':data.verified?'Commissioned':'Pending commissioning'}</strong></div><p class="panel-note">Your GridUbuntu reference identifies your residence. Provider identifiers and credentials are managed securely by your operator.</p></section><section class="panel"><div class="panel-heading"><div><span class="overline">REPORTED EQUIPMENT</span><h2>Connected devices</h2></div></div>{#if data.devices?.length}{#each data.devices as device}<div class="device-row"><span class="metric-icon"><Icon name="system"/></span><div><strong>{device.name}</strong><small>{device.firmware?`Firmware: ${device.firmware}`:'Firmware not reported'}</small></div></div>{/each}{:else}<div class="device-empty"><Icon name="system" size={32}/><p>Equipment details will appear after the installation is connected.</p></div>{/if}</section></div>
<section class="panel readings-panel"><div class="panel-heading"><div><span class="overline">TECHNICAL READINGS</span><h2>A closer look</h2></div><span class="panel-tag">Latest available values</span></div><div class="table-scroll"><table><thead><tr><th scope="col">Measurement</th><th scope="col">Reported value</th><th scope="col">Reported at (CAT)</th><th scope="col">Availability</th></tr></thead><tbody>{#each readings as [key,label,unit]}<tr><th scope="row">{label}</th><td>{formatValue(metrics[key]?.value,unit,2)}</td><td>{formatTime(metrics[key]?.reportedAt)}</td><td>{metrics[key]?metrics[key].freshness==='recent'?'Reported':'Delayed / check time':'Not reported'}</td></tr>{/each}</tbody></table></div><p class="panel-note">Unavailable values are not replaced with zero. Generator and grid information depends on the installation’s actual configuration and sensors.</p></section>
<div class="notice neutral"><Icon name="lock"/><div><strong>Your system stays under operator control.</strong><p>This portal cannot switch devices, change inverter settings, or alter charging behaviour.</p></div></div>
